-- 0008 — game scores (GAME-7). One row per played run of a Muscle Games game.
-- run_id is generated by the game; re-sending the same run (e.g. Diameter resumed after leaving) updates the row.
-- Rollback (manual): DROP TABLE game_runs;
CREATE TABLE game_runs (
  id             INTEGER PRIMARY KEY AUTOINCREMENT,
  student_id     INTEGER NOT NULL REFERENCES students(id) ON DELETE CASCADE,
  enrollment_id  INTEGER REFERENCES enrollments(id) ON DELETE SET NULL,
  class_id       INTEGER REFERENCES classes(id) ON DELETE SET NULL,
  run_id         TEXT    NOT NULL,
  game_id        TEXT    NOT NULL CHECK (game_id IN ('balloon-pop', 'group-sort', 'diameter')),
  score_key      TEXT    NOT NULL,                  -- 'balloon-pop' | 'group-sort:memory' | 'group-sort:conveyor' | 'diameter'
  score          INTEGER NOT NULL,
  stars          INTEGER NOT NULL CHECK (stars BETWEEN 0 AND 3),
  completed      INTEGER NOT NULL DEFAULT 1,        -- 0 = left before the end (score of what was played)
  summary        TEXT    NOT NULL DEFAULT '',
  mistakes       TEXT    NOT NULL DEFAULT '[]',     -- JSON: [{ prompt, yours, answer, why }]
  achievements   TEXT    NOT NULL DEFAULT '[]',     -- JSON: ["stars3", ...]
  created_at     TEXT    NOT NULL,
  updated_at     TEXT    NOT NULL,
  UNIQUE (student_id, run_id)
);
CREATE INDEX idx_game_runs_class ON game_runs(class_id, score_key);
CREATE INDEX idx_game_runs_student ON game_runs(student_id, score_key);
